<style>
* {
  margin: 0;
  padding: 0;
}

#box {
  display: grid;
  width: 100vw;
  height: 100vh;
  gap: 0;
  grid-template-rows: 30px v-bind("headstyle.h + 'px'") auto;

  &>#head {
    height: v-bind("headstyle.h + 'px'");
    width: 100vw;
  }

  &>#body {
    width: 100vw;
    display: grid;
    grid-template-columns: 130px auto;

    &>div:nth-child(1) {
      /* display: grid;
      grid-template-rows: repeat(7, 45px);
      justify-content: end; */
      display: flex;
      flex-wrap: wrap;
      justify-content: end;
      align-content: flex-start;
      gap: 5px;
      width: 130px;
      height: 100%;
      box-sizing: border-box;
    }

    &>div:nth-child(2) {
      width: calc(100vw - 130px);
      height: calc(100vh - 50px - 30px);
      border-style: solid;
      border-width: 1px;
      transform: scale(0.99);
      border-radius: 8px;
      box-sizing: border-box;
      border-color: #f6cad5;
      background-color: #26272c;
    }
  }
}
</style>
